src = open('fr.html', encoding='utf-8').read()
for col, out in ((1, 'index.html'), (2, 'en.html')):
    s = src
    for row in T:
        if row[0] not in s:
            raise SystemExit(f'Texte introuvable dans fr.html : {row[0][:70]}')
        s = s.replace(row[0], row[col])
    open(out, 'w', encoding='utf-8').write(s)
    print('écrit', out)
